def calculateScore(s: str) -> int:
    score = 0
    marked = set()
    mirror = {chr(i): chr(219 - i) for i in range(97, 123)}  # Create a mapping for mirrors
    for i in range(len(s)):
        if i in marked:
            continue
        for j in range(i - 1, -1, -1):
            if j in marked:
                continue
            if mirror[s[i]] == s[j]:
                score += i - j
                marked.add(i)
                marked.add(j)
                break
    return score

