from typing import List


def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    dp = [[[float('-inf')] * 3 for _ in range(n)] for _ in range(m)]
    dp[0][0][0] = coins[0][0] if coins[0][0] >= 0 else 0

    for i in range(m):
        for j in range(n):
            for k in range(3):  # k = number of neutralizations used
                if i == 0 and j == 0:
                    continue
                current_coins = coins[i][j]
                if current_coins < 0:
                    if k > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1] + max(0, current_coins))
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1] + max(0, current_coins))
                else:
                    if i > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + current_coins)
                    if j > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + current_coins)
                if k < 2:
                    if i > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k+1] + current_coins)
                    if j > 0:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k+1] + current_coins)

    max_amount = float('-inf')
    for k in range(3):
        max_amount = max(max_amount, dp[m-1][n-1][k])
    return max_amount if max_amount != float('-inf') else 0

